process.on('beforeExit', () => {
  // beforeExit fires when event loop is empty but process is still alive
  // This is our chance to clean up bash processes before they prevent exit
  cleanupAllSessions()
})

process.on('SIGINT', () => {
  cleanupAllSessions()
  /* c8 ignore next */
  process.exit(0)
})
